      "explanation": "Saksa keeles kasutatakse sõna „der Reis” ainult ainsuses, seepärast peab tegusõna lauses olema ainsuse vormis (näiteks „ist”, mitte „sind”). Eesti keeles öeldakse samamoodi ainsuses „riis”.",
